import{_ as a,o as e,c as t,a3 as o}from"./chunks/framework.DdpBa4_E.js";const i="/ReadBooks/assets/image-093.I-CzOV20.jpg",s="/ReadBooks/assets/image-094.C60Bwavq.jpg",r="/ReadBooks/assets/image-095.DqFJBH5j.jpg",n="/ReadBooks/assets/image-096.CZrcH2Mo.jpg",l="/ReadBooks/assets/image-097.BhzB2Npl.jpg",k=JSON.parse('{"title":"第七章 挑战与革新","description":"","frontmatter":{},"headers":[],"relativePath":"books/jingying-weilai/10-第七章挑战与革新.md","filePath":"books/jingying-weilai/10-第七章挑战与革新.md","lastUpdated":1795076791000}'),d={name:"books/jingying-weilai/10-第七章挑战与革新.md"};function _(c,p,h,m,g,u){return e(),t("div",null,[...p[0]||(p[0]=[o('<h1 id="第七章-挑战与革新" tabindex="-1">第七章 挑战与革新 <a class="header-anchor" href="#第七章-挑战与革新" aria-label="Permalink to &quot;第七章 挑战与革新&quot;">​</a></h1><h2 id="晚上去参观美术馆吧" tabindex="-1">晚上去参观美术馆吧 <a class="header-anchor" href="#晚上去参观美术馆吧" aria-label="Permalink to &quot;晚上去参观美术馆吧&quot;">​</a></h2><p>首尔市内有美术馆、历史博物馆、大公园等文化设施，但在以前，此类文化设施大多很晚开门、很早关门。</p><p>比方说，在首尔生活的公司职员甲先生想带乙小姐去参观美术馆，可是当他们下班后急匆匆赶到美术馆时，美术馆已经关门了。于是，甲先生只能经常在美术馆前面的汉堡店和乙小姐见面。由于闭馆时间太早，“上班族”平时根本没有机会欣赏美术馆内展出的作品。</p><p>“即使有一位市民感到不便，我们也应该努力去改正。何况现在有那么多人感到不便，为什么有关部门不作改变呢？”</p><p>虽然道理简单明了，可要改掉一个存在很久的“习惯”也不是那么容易的。</p><p>在我就任市长不久后的一个周日，恰好有机会参观首尔大公园。大公园里非常热闹，大多是举家外出、手拉手游玩的市民。但是，有一个现象让我觉得很吃惊：在休假日，公园里的工作人员反而比平时要少，因为工作人员也要和其他市民一样在家休息。</p><p>“休假日客流量比平时要大，照理说应该安排更多工作人员才对，怎么会反而有减无增呢？这样的体制必然是低效的。”</p><p>我不能理解为什么像大公园这样的文化服务机构实行的是和一般企业同样的上下班制度。恐怕再怎么解释，也很难逃出行政方便主义的想法。</p><p>“如果一个人平时工作很忙、不能早下班，休假日又又要加班，那他就没办法去美术馆、博物馆或动物园了吗？”</p><p>趁这次机会，我决心一次性解决这些问题。事实上，那些服务机构的公务员并没有真正意识到问题的存在。当然，我也可以直接下达命令：延长文化设施的开放时间，改变上下班制度。但如果使用强制性方法，效果会怎样呢？经过考虑，我决定宁可多花一些时间，采用引导的方式，促进自觉改变意识。一次会议结束后，我问一位负责人：“我特别想看看这次美术馆展出的作品，可白天太忙没时间，工作结束后再去吧，又过了开馆时间，你说怎么办呢？”“您放心，我们会根据您的时间调整开放时间。”对于我的提问，这位负责人毫不犹豫地做出了回答。虽然这样的回答在我的意料之中，但我还是很失望。“因为是市长就有优待，这样行吗？”我以开玩笑的口吻，稍稍涉及了问题的核心。但那天，我只是点到为止，没有为难这位负责人。下次开会的时候，我又把他叫住了。“有一位我认识的美术学者，他说很想看看这次展览。但他也和我一样，没法在美术馆开馆的时间过去，你说怎么办呢？”这一次，这位负责人似乎感觉到了什么。但他并没有说出“要变更开馆时间”之类的话，我也没再说什么，就让他回去了。就这样过了一个多月，我最后一次“试探”他：“这几天你们美术馆是不是在展出国内很少能看到的作品？有很多人都想去看一看，但闭馆时间太早，他们都找不到机会去看。”这位负责人终于恍然大悟。我决定再耐心地等一等，看看他们会拿出什么样的解决方案。三个月后，我收到了一份审批文件。“拟延长市立美术馆和历史博物馆在市民工作日的开馆时间，大公园等设施调整工作人员作息制度，以便在休假日为市民提供更好的服务。”虽然花了三个月，但这绝对不是浪费时间。最终的结果是有关负责人经过深思熟虑和多次讨论得出的，而且经过商议，他们也意识到了延长开放时间的必要性。</p><p>我本人是一个急性子，总是希望把手头的工作尽快完成，但如果任由性格行事，单方面下达指示、责令有关部门尽快实施，这样的做法会取得好的效果吗？如果我的强制性指令并没有获得有关负责人认可，反而引起他们的不满，那么我“强行干涉”即使短期内有效，在我任期结束、下一任市长赴任之前，谁又能保证不会恢复到原态呢？</p><p>真正的变化应当是自发性的，因而也是需要花时间来磨合的：尤其是要打破长久以来形成的惯例，更不能草率、强制地要求变更。在企业经营中，领导者或CEO引导员工自觉性改变也具有重要意义。</p><p>国际畅销书作家吉姆•科林斯指出：“有目标的企业CEO不是告诉时间的人，而是制造钟表人。”如果说，领导者凭一已之力改变企业是“告诉时间”的行为，那么引导组织成员自发改变则是“制造钟表”的行为。当然，主导变化方法论也不是那么容易掌握。</p><p>“是用强制性方法呢，还是靠成员自觉？”这样的问题应当根据实际情况而定。强制性方法能够导致即刻、明显的变化，但遇到的阻力也会很大；反之，依靠成员自觉的方法遇到的阻力较小，但也面临多支付时间和费用的风险。如果企业或组织处于危机状态或成员惰性很强，那么使用强制性方法就不可避免，但如果情况不是那么紧迫，则使用自觉性方法为佳，因为让组织成员自己感觉到变化的必要性是非常重要的。如果靠强制性方法主导变化，一旦领导者离开组织，所有的变化可能都会恢复原态。</p><p><img src="'+i+'" alt="参加“世界的节奏”文化庆典" loading="lazy"></p><p>参加“世界的节奏”文化庆典</p><p><img src="'+s+'" alt="科举再现文化活动" loading="lazy"></p><p>科举再现文化活动</p><p><img src="'+r+'" alt="“你好首尔”服装秀活动" loading="lazy"></p><p>“你好首尔”服装秀活动作为民选三期的首尔市长，我所肩负的使命，用一句话概括就是起到革新家的作用。首尔的公务员组织最需要的就是“革新”。为了把首尔打造为世界一流城市，变化与革新已是当务之急，但与此同时也面临诸多阻力。革新意味着否定从前、转换方向，因此必然招致一部分人的反对。在这样的情况下，我认为应当以依拿自觉性方法为主，辅以必要的强制性措施。让组织成员理解革新的必要性是非常关键的，因此构建与组织成员的信赖至关重要。当然，信赖不是一两天就能形成的，需要领导者与组织成员坦诚相待，在一次次接触过程中逐渐积累。我上任市长后，有时会和高层人员一起参加文化活动。我很享受和他们欣赏音乐会或舞台剧后一起喝啤酒、聊天的时光。因为不是在冰冷的会议室，大家就会自然而然地说出一些心里话。如果时间允许的话，我也会和工作在第一线的公务员们一起参加文化活动。公务员们的反应往往比预想的还要好。还记得有一回，我上任后第一次和下属的女职员们一起欣赏晚上去参观美术馆吧！</p><p><img src="'+n+'" alt="和RAIN在一起" loading="lazy"></p><p>和RAIN在一起</p><p><img src="'+l+'" alt="和宝儿在一起" loading="lazy"></p><p>和宝儿在一起音乐会。在演出结束后的会餐中，身边一位女职员突然挽起胳膊，开始用自己的相机拍照了。“市长，茄子！”大家笑成一团，原先有些不自然的气氛一下子变得融洽了。“市长，来个交杯酒吧。”另一位女职员举起胳膊提议干杯。后来几次聚会也是如此。和基层职员们一起喝啤酒时，气氛总是乐融融的。一些高层职员不敢提的问题，下层职员也会大方地提出来。有时，陪坐的区厅长们甚至因为下属的冒昧而脸色大变。这种时候我心里其实特别高兴，因为我感觉到，挡在我们之间的那堵墙已经消失了。由于工作繁忙，我不能经常和他们在一起畅谈，但那些坦率、真诚的对话，的确让我受益韭浅。</p><p>晚上去参观美术馆吧！</p><p>“各自敞开心怀，才能彼此交心。”这是一个朴素而珍贵的经验。也许是真诚沟通推倒了那堵无形的墙，我上任后不久，下属们对我的态度不知不觉改变了。以前在楼道里相遇时会悄悄躲开的职员们，不知从什么时候起，开始亲热地和我打招呼了。我相信这不只是单纯的好感，更是发自内心的信任。</p><p>如果说在首尔市政厅刮起的变革之风取得了成功，那么全市4.5万名公务员和我之间形成的信任就是推动变革的原动力。无论是采用强制性方法，还是依靠成员自觉，只要领导者与成员之间达成了牢固的信任，风险负担就能大大减轻。</p><h2 id="竞争力从哪里来" tabindex="-1">竞争力从哪里来？ <a class="header-anchor" href="#竞争力从哪里来" aria-label="Permalink to &quot;竞争力从哪里来？&quot;">​</a></h2><p>上任首尔市长后，我努力在市政经营中导入企业意识，把我在企业经营中积累的知识和经验运用到市政工作中。那么，企业意识的核心是什么呢？我想把它定义为挑战精神——不安于现状、积极接受变化的精神；不轻易在困难面前低头、勇于挑战的精神。做到这一点不容易，但也绝非不可能。</p><p>我在生活、工作中遇到过许许多多的困难，但不管困难有多大，我都没有轻易放弃，总是拼尽全力去挑战、去奋斗。也许这种精神是在小时候的困境中自然养成的。从那时起，我的价值观的核心就是遇到挫折绝不放弃。</p><p>当今世界正处于一个巨变的旋涡之中。在超越国界的全球化市场中，在日新月异的数字时代，企业和个人被迫投入在日益激烈的竞争中。从这个意义上说，挑战精神是获得生存的必备条件。</p><p>真正的挑战者应该领先于时代变化。以前，对时代变化最敏感的是企业。如今，公共机构为了适应时代发展也在努力尝试变化与突破，提高服务意识便是这种努力的一方面。</p><p>我曾经多次提到“国家经营”和“CEO型领导者”的说法。很多人觉得这种理念很陌生，冷嘲热讽者也不在少数。</p><p>“因为是企业CEO出身，就想把首尔当成一个企业来经营吗？”</p><p>事实上，这种理念并不是我首创的。国际上各个领域都在呼唤 “CEO型领导者”的出现。随着冷战时代的结束，许多国家的领导者开始思考：“如何才能让国民生活得更好？”转变政治统治观念、为国民提供更积极服务的时代已经到来。</p><p>一个具有创造性的人会经常问自己：“我还能做些什么？”进取性心态很重要，但在努力过程中不能忽视对成果的评估。以成果为中心的思考方式可以让人更加冷静、更加贴近现实地考虑问题。比如说，有一个和你关系很好的组织成员，作为优秀的领导者，你应该把私人感情放在一边，优先考虑这个组织成员的成果价值。这种方式看上去有些冷酷，但对整个组织来说是有益的。为了争取最大成果，朝着自己和组织的潜力最大化的方向思考，只有这样的CEO，才是真正具有挑战精神的领导者。</p><p>那么，一个具有挑战精神的人就一定能成为杰出的领导者吗？</p><p>答案自然是否定的。</p><p>杰出的领导者不仅需要自己具备挑战精神，还应当把这种挑战精神传染给组织成员。当每一位成员都变成积极的挑战者时，这个组织才会拥有强大的竞争力。</p><p>竞争是使组织充满活力的一剂良方。没有竞争的组织会陷于惰性，越来越退步。在担任首尔市长期间，我十分注重部门间的合理竞争，希望各个部门、各个成员之间通过竞争深化企业意识。</p><p>有时候，某一个项目并不能特别清晰地划归某一个部门主管。遇到这种情况，我不会随便指派给某一个部门，而是等着哪个部门主动申请负责这个项目。这样慢慢地，从一开始的犹豫，到后来的积极争取，部门之间自然形成了竞争的风气。设立国际会议事务局（Convention &amp; Visitors Bureau）就是引入部门间竞争的一个例子。</p><p>国际会议事务局是以吸引具有影响力的国际会议为目标的组织，除了提供会议场所信息之外，还要为主办单位和与会人员提供必要的服务，促进会议活动顺利进行。</p><p>国际会议事业是一项新兴的服务产业，有利于提升城市形象，吸引更多游客和投资者。召开国际会议本身就能创造高附加值，国际会议参与者平均每人的消费额相当于普通游客的几倍。因此，世界各地的大城市都在想方设法吸引国际会议在本城市召开。</p><p>“首尔政府应当积极支持国际会议事业的发展。”</p><p>“为了推动国际会议事业，市政府应当支援民间企业。”</p><p>在我上任以前就有许多这样的意见，但市政府的态度一直比较消极，因为他们认为，民间企业在这方面已经做得很不错了。事实上，放眼世界，无论是民间企业主导，还是政府部门主导，绝大多数一流城市都设立了国际会议事务局，积极筹办国际会议。在韩国国内，釜山、大邱、济州岛等地方自治政府也在积极筹备国际会议事务局，各个国家、城市间的竞争日益激烈。在这样的情况下，首尔如果一味放手交给民间去运作是很难在竞争中取胜的。</p><p>我上任伊始，就新设立了新闻局下属的营销负责官。在我的理念中，管理城市和管理企业一样，都需要有积极的营销意识和科学的营销手段。</p><p>“我们首尔市是不是也应该设立一个国际会议事务局？”</p><p>有一天，国际会议相关团体通过营销负责官提出了这样一个方案。当时我自己也正在构想如何培养国际会议产业，因此欣然答应了。但是在后来的讨论会议上，没有一个部门站出来要求负责这一项目。严格地说，国际会议产业是属于产业局或文化观光局的职责范围，不知道是否因为之前一贯的消极态度，没有一个部门主动站出来。</p><p>“从城市营销角度看，这是一个很好的机会，我们部门想试试看。”</p><p>毛遂自荐的正是那位营销负责官。我赞许地对他说：</p><p>“发展国际会议产业是打造国际一流城市的基础，你们努力试一试吧。”</p><p>营销负责官随即开始了筹备工作，但进展得并不顺利。为了召开与清溪川相关的国际会议，他们需要产业局和文化观光局的协助。国际会议设施归产业局管辖，而食宿设施又归文化观光局管辖。掌握国际会议支援基金的也是产业局和文化观光局。另外，国际会议策划企业、旅游业界、酒店等相关部门的意见也很混乱，筹备工作遇到了层层阻力。</p><p>“由市政府和企业各出资50%，给参与的企业提成。配比资金（match-fund）方案也许会受到业界的欢迎。”</p><p>提出配比资金方案之后，这个项目重新有了朝气。在时机成熟时，我们给各个酒店代表发了邀请信，以便开展实质性的协商。出乎我们意料的是，协商会议当天来了两倍于我们邀请人数的企业代表。从那以后，国际会议筹备工作渐渐走上了正轨。虽然后来也有过几次曲折，但首尔国际会议事务局最终在2005年成立了。</p><p>设立国际会议事务局的计划顺利完成后，其他部门的想法也开始转变了。再有其他项目时，各个部门都开始表现出积极的姿态。试想，如果当初我安排一个态度消极的部门接手国际会议事务局项目，结果会怎样呢？</p><p>国际会议事务局成立后，首尔市承接国际会议的能力从世界第15位上升到了第10位。</p><h2 id="节约10-的预算" tabindex="-1">节约10%的预算 <a class="header-anchor" href="#节约10-的预算" aria-label="Permalink to &quot;节约10%的预算&quot;">​</a></h2><p>说起来，创建合同审查科还是我在竞选首尔市长时提出的构想。</p><p>“当选市长后要为首尔节约10%的预算！”这句话不是空口承诺，节约10%的预算是有充分可能性的。</p><p>以前，几乎所有项目的前期预算和实际花费都是一致的，预算100亿元就花了100亿，预算80亿元就花了80亿。</p><p>每次预算的金额怎么会到工程结束时正好用完呢？对于这个疑问，或许可以从市民们的讽刺中得到暗示：“预算的钱如果剩下了，肯定是不行的嘛。</p><p>所以本来好好，还得再挖一挖。”这不是哪个人特意传给我的话，而是以前街头巷尾的流行语。</p><p>每年年末，洞、厅等机关为了处理剩下的预算就经常修路、修设备，像例行公事一样年复一年反复折腾，因为如果不花掉剩下的预算，这一部分就会从下一年的预算中扣除。</p><p>我上任以后就决心要改变这种不合理的惯例，实行高强度预算节约政策，以此为目的设立了合同审查科。</p><p>以前，工程合同都是在各部门内部处理的，因此信息的共享、协调或联系都很不充分。</p><p>虽然有基本构架，但要做出一个通用范本并不容易。</p><p>合同审查科破格改变了以前的合同惯例，标准单价和高级信息等实现了共享。</p><p>当然也有副作用。</p><p>一开始，合同审查科频繁地与签订合同部门发生冲突，虽然该部门已经做了很紧的预算，但合同审查科还是要求进一步紧缩预算。</p><p>“你们和我们都不是专家，凭什么就让我们削减预算？”“按这个金额吗？那你们自己做做看吧。”合同审查科职员和其他部门的职员之间一度关系紧张，甚至有职员把合同审查科叫作“死神”，摆出一副拒之千里的姿态。</p><p>但就是在这样的困境中，合同审查科渐渐站稳了脚跟。</p><p>另一方面，首尔市管辖的施工企业也与合同审查科产生了许多矛盾。以前，如果使用新的施工方法或新的工程技术，单价一定会提高，但合同审查科成立以后，这个惯例就行不通了。他们会在施工前期进行严密的分析讨论，研究新技术是否必要、是否可行，因此难免引起施工企业的抵触。</p><p>举个例子来说：在苑南、弥阿高架路拆除工程中，就发生了切割施工企业不予合作的情况。他们拒绝提交相关资料，要么就是敷衍了事。</p><p>“我们明确说过请你们提交资料，怎么没带来呢？”</p><p>“以前从来没有对资料进行过讨论，现在为什么突然要这么做？”</p><p>“从现在开始，任何工程都要从讨论资料开始。”</p><p>“我们不能提供资料，这是我们的商业机密！”企业拒绝提交资料，但这种不合作态度的最终受害者是企业本身。经过广泛收集意见和反复讨论，对于钻研切割工程，首尔市制定了一个合理的预算标准，并且根据这个标准成功完成了施工项目。在两条高架路拆除工程中，节约预算达到了3亿韩元。</p><p>经过艰苦工作和不懈努力，合同审查科在3年间为首尔市节约了4472亿韩元。</p><p>我第一次和一个部门的全体职员聚餐就是在合同审查科。在我看来，这支节约预算突击队尤其需要我们的鼓励与肯定。</p><p>事实上，合同审查科成立之后，各个部门就逐渐表现出了节约预算的积极态度。部门之间的竞争也使得节约的氛围越来越浓。施工企业在经过一段时间磨合之后，也逐渐抛弃了利用不当方法获得不当利益的做法，开始更努力地通过项目经费的科学管理、新技术开发等方式节约成本。</p><p>建设安全本部、上水道事业本部等市政下属机关也自行设立了成本分析部门，开始关注节约预算的问题。</p><p>这种竞争性的节约意识不仅在首尔蔚然成风，还扩大到了全国范围。</p><p>蔚山广城市和忠南牙山市也相继设立了合同审查科。</p><p>在建设的第一线，施工现场的器材使用、向民间租赁闲置设备或综合购买材料、在道路标识或手册上招集广告等，即使没有人督促，各个环节也会十分注意成本控制。</p><p>首尔市在2005年一年就成功节省了8000亿韩元预算。</p><p>节省的费用一方面用于增加市民福利，另一方面用于偿还地铁施工债务。</p><p>不过我认为，最难得的还是由上至下的节约意识形成，以及由此扩散到各个成员、部门间的竞争意识。</p><p>美国管理学者道格拉斯•麦格雷戈在20世纪60年代就提出了当时还很新鲜的“X理论与Y理论”。</p><p>X理论是指“大多数人是懒惰的、逃避劳动的，只有在经济动机的推动下才会去劳动，没有接到指示和命令就不会实行”的假设。</p><p>根据X理论，除了金钱上的刺激以外，赋予动机的方法只有指示和命令。</p><p>相反，Y理论是指“人希望发挥自己的能力，通过劳动实现自我价值，不是他人强迫，而是为自己设立的目标而劳动”的假设。</p><p>道格拉斯•麦格雷戈“X理论与Y理论”的核心问题就在于：如何让成员投入工作？X理论排斥人的自发性、自我实现等动机，表现出许多局限性。</p><p>以X理论为基础的组织渐渐被时代发展所淘汰了。</p><p>在一定的时期或状态下，指示和命令是有效的，但依靠这种方法绝对不能发展为一流的企业或组织。</p><p>近年来，大部分企业或组织都倾向于Y理论，注重成员的主观能动性。</p><p>“新风经营”、“FUN经营”、“恢复员工士气”等项目也是以道格拉斯•麦格雷戈的Y理论为依据展开的。</p><p>如果说有活力的组织是以Y理论为基础的，那么赋予动机就更显其重要性。</p><p>我希望首尔有竞争之风，但强制竞争就能解决问题吗？强制实行往往达不到预期效果，赋予成员动机、引导竞争氛围才是长期有效的良方。</p><h2 id="现在是专家时代" tabindex="-1">现在是专家时代 <a class="header-anchor" href="#现在是专家时代" aria-label="Permalink to &quot;现在是专家时代&quot;">​</a></h2><p>我一直相信“人才可以改变世界”这句话。这是我经历了艰难的成长、求学、事业开拓之后，始终珍藏在内心的一个信念。</p><p>我在12年里从低层职员上升到CEO位置，靠的是企业主的信任。为了报答这份信任，我更加努力地工作。在这12年里，我个人的境遇改变了，我生活的国家也发展了。</p><p>依靠这些经验，我相信通过努力，个人、社会、国家都是可以改变的，而引导这种变化的正是人才。个人的竞争力最终将汇聚为集体的竞争力。</p><p>那么，在如今这个全球化时代，在竞争日益激烈的国际环境中，我们需要的究竟是什么样的人才呢？</p><p>我认为，能被这个时代所承认的人才，就是具有时代使命感、开放性思维和挑战精神的专家。</p><p>在当今世界，一切都在飞速变化，信息通讯的变化速度更是超出想象。对信息的利用能力与程度拉开了人们之间的距离。个人之间、国家之间的信息两极化很快就会导致收入的两极化。</p><p>与劳动量相比，劳动的效率更显重要。有效用的劳动正在持续替代无效用劳动，今后这种替代还会更加迅速、深入，其导致的结果就是个人和企业必须发掘效率更高的劳动领域。</p><p>一个优秀的人才应当正确认识这种时代的趋势，并且应当具有献身于社会的使命意识。有使命意识的人会自发培养个人欠缺的能力，更好地为社会服务。</p><p>与具有多方面才能的人相比，拥有一技之长的专家或许更能适应这个急速变化的时代。固然，在某些领域需要具有多方面才能的人，但随着时代发展，如果不能成为专家，将很难获得生存。即使是专家，也不能只满足于单纯的差异性。正如首尔要和世界一流城市竞争一样，每个专家也都要和世界一流的专家展开竞争。在市政工作中，如何运用专家是一个重要课题。尤其在官僚组织中，提高工作的专业性、效用性，专家参与尤显重要。公务员和相关领域专家的协作程度往往决定着工作的成败。</p><p>在首尔“新城市”（NEW TOWN）开发事业中，相关专家的参与就起到了非常重要的作用。</p><p>新城市项目的目标是开发相对落后的首尔江北地区，缩小江南与江北的差距。首尔是一座历史悠久的城市，从朝鲜王朝太祖李成桂定都以来，经历了六百多年的沧桑。城市功能性老化、缺乏整体规划性是城市建设面临的一大难题。当然，这不是首尔独有的现象，世界上任何一座古老的城市都存在这样的问题，对旧城加以开发改造也经常引起大的争论。首尔要做的是再开发、再建筑，改善城市整体居住环境。</p><p>但是，以前的再开发、再建筑工程往往只注重当时的开发利益，缺乏对周边基础设施的整体考虑。虽然房子改良了、户数增加了，但是道路、管道、学校、公园等生活基础设施并没有跟上。人口虽然增加了，但如果周边设施没有改善，居民的生活质量反而会下降。</p><p>正因为这样的恶性循环，才出现了“江北地区开发了，房价却下降了”这样的奇怪现象。相反，江南地区因为新城的便利条件，公园、学校等周边配套设施的完善，房价一直持续上升。</p><p>江北和江南的差距越来越大，这成了一个亟待解决的社会问题。新城市开发项目正是基于这样的现状而提出的。具体的构想是以大型生活圈为单位，把再开发的地区捆绑为一体，由首尔公共部门支援道路、学校、公园等基础设施的建设。</p><p>如果说，政府官员和城市学者创造了“新城市”这样一个概念，那么，具体的勾画、实践工作还得靠相关的专家来掌握。因此，我们在新城市开发项目中导入了MA（Master Architect）制度。</p><p>MA小组由建筑、城市设计等领域拥有丰富经验和知识的专家组成。在新城市开发项目中，MA小组不是按照以前的平面开发计划，而是立足于立体开发，制定全方位的开发计划。</p><p>由于他们的参与，新城市开发项目最终确立了符合地区特性、注重环境持久性、以人性化为中心的开发理念。新城开发型、居住中心型、城市中心型等不同地区的不同定位也是由MA小组运作的。</p><p>除了城市开发项目之外，金融专家、通商专家等也在其他领域的工作中起到了积极作用。</p><p>但是，在强调外部专家的专业支持的同时，我们更加应该注重公务员组织自身的专家精神的培养。</p><p>“只有提高韩国公务员的整体竞争力，韩国才能改变。如果首尔市的公务员有了好的转变，整个韩国的公务员也会随之发生变化。”</p><p>这是我出任首尔市长后接受媒体采访时说的话。改变公务员面貌是我和市民的约定。</p><p>变化应该从最基本的一点一滴开始。与巨大的爱国心相比，加强自己领域内的专家精神更具实际意义。如果具备了专家精神，就会自然衍生出为市民服务的精神。首尔市的人才首先应该是满足这种要求的人。</p><p>我上任后很快着手从各个部门里选拔组长、科长、局长，派到国外去学习。</p><p>“李明博市长到底想干什么呀？”</p><p>或许大部分公务员都会有这样的疑问。新市长不召开研讨会，而是急急忙忙花那么多钱把公务员派到国外去，这是走的哪一招啊？</p><p>其实我的意图很简单，我就是想让他们亲眼看看世界先进城市的行政管理。</p><p>“公务员组织应该更具竞争力，所以要把企业意识体制化，要强化对市民的行政服务意识……”</p><p>与其听这样的唠叨，还不如让他们直接去体验，“百闻不如一见”。</p><p>出于这样的目的，建筑科长被派往城市建设最好的地方去学习；福利局长被派往福利体系最完善的地方去学习；环境科长、策划科长、文化局长也是一样。派往国外的公务员回来以后，又对所有公务员进行了三天培训。地点在龙仁的三星集团研修院，从副市长到9级公务员无一例外全部参加。</p><p>培训的方式也和过去完全不同，不是单纯地让讲师在讲台上讲三天课，而是在民间机关制定系统性的日程，亲自体验、自我反省。培训前和培训后的变化也在专家的关注范围内。我们不要求有多么巨大的变化，相信只要有一点细微的改变，就能引起整个行动的变化。</p><p>成员的变化应该是自上而下的，部门领导者应该是变化的主体。</p><p>上任伊始我就传达过这样的信息：</p><p>“以前是官职越高，越不了解现场情况和工作进展。现在的首尔不需要这样的领导者。我希望主事、组长、科长不要再把下属起草的东西变换几个字后就向我报告。”</p><p>之所以如此强调，也是因为以前就出现过这样的情况。作为一个领导者，即使不能详细了解某个方案，也应该大体掌握工作的基本脉络。但以前的情况是如果不找直接负责人，连基本的统计数据都无法了解。</p><p>为了革除这种充满惰性的官僚主义，我要求在定期举行的室长、局长研讨会上，各个负责人要汇报各自部门的工作现状，其他人员可以提问，甚至提出反对意见，然后进行辩论。项目的策划重点、促进过程中的障碍、克服障碍的方案等都是讨论的对象。尤其在室长、局长以上级别官员参加的会议上，各个负责人一定要详细了解自己部门的工作。如果拿着职员们写好的材料去参加研讨，只会让自己出丑，在这方面是没有情面可讲的。</p><p>另外，通过这样的交流、辩论，各个部门之间也实现了一定程度的资源共享。文化局长也可能对城市计划局的工作提意见，交通局长也可以为文化局出谋划策。</p><p>我不认为靠几个专家就能改变整个组织。要想让组织强盛起来，就应该让所有成员都成为各自领域的专家。我上任后促进的培训活动就是为了培养这样的专家，从而提升整个组织的竞争力。</p><h2 id="拥着反对者一同前进" tabindex="-1">拥着反对者一同前进 <a class="header-anchor" href="#拥着反对者一同前进" aria-label="Permalink to &quot;拥着反对者一同前进&quot;">​</a></h2><p>要使自己促进的变革取得成功，必须获得强烈拥护自己主张的支持力量。</p><p>“发现拥护者，与他们沟通，得到他们的支持，这是促进变革的核心成功因素。”</p><p>这是《强力沟通术》（Powerful Conversation）一书的作者菲尔•哈尔金斯的主张。他通过对大量企业案例的分析，指出在大部分企业中，热烈响应的集团是促进变革的主要力量。</p><p>正如菲尔•哈尔金斯所指出的，变革不可能只靠领导者一个人的力量来完成。失败的改革大多是因为核心人才没有发挥各自的能力。核心人才应当渗透到组织的各个部分，主导和引导变化。在这个过程中，变化就会自然渗透到组织文化中。</p><p>有一点要注意的是，对核心人才以外的中层集团也应该多加关注，毕竟中层集团占据着组织的大多数，应当不断地赋予其动机，使他们成为变革的核心力量。以足球运动为比喻，如果中场力量薄弱，前场的攻击力再强也不能取得胜利。在制定比赛策略时只考虑前锋的教练不可能成为一流的教练。另一方面，在组织内部也经常会有持反对意见的集团。作为领导者，应当如何处理对自己的工作目标和工作方式持反对意见的人呢？一般有三种回答：第一是说服，第二是包容，第三是剔除。在说服不了、又无法包容的情况下，为了整个组织的顺利运转，最后只能采取剔除的方式。但在现实中，这种方法实行起来很难，也不是大家希望看到的局面。我的主张是：拥着反对者一同前进。包容反对者是变化经营和人才经营的一种方法。在我担任首尔市长期间，发生过这样一件事：有几个区厅长对一位负责一线工作的局长表露过不满。“什么事情一到那边就杳无音信了，工作没法展开。”“只要那个人还待在那个位置上，我们区里什么项目也上不了。”不满的原因在于这位局长对开发项目的限制太过严格。站在各个区厅的立场上，一定程度的开发是必要的，只有这样才能提高就业率、增加税收，地区经济才能复苏。但是，那位局长更加偏重限制需求的政策，所以对开发可行性的标准定得非常严格，很多项目计划在他那里都得不到批准。事实上在发展政策上，民选三期和民选二期是有差异的。民选二期政府或许是把焦点放在抑制需求上，而民选三期则侧重均衡发展。“市长，利用这次机会换个新人吧。”不仅仅是区厅长和市议员，由于民怨较大，连幕僚们也异口同声地这样主张。但是，我并没有撤换那位局长。主张限制开发是他个人的政治哲学，他不是为一己私利才这么做的，只是延续政策的一贯性。他是说服的对象而不是剔除的对象。</p><p>在工作中，遇到反对意见是难免的。一位优秀的领导者应当有能力包容反对者、说服反对者，拥着反对者一同前进。只有这样才能形成健康的人事习惯，使组织更加牢固。如果一听到反对意见就予以剔除，最终只会使自己陷于困境。</p><p>领导者制定的目标最终是通过人才得以实现的。人才开发是领导者必须面对的重要课题之一。领导者应当系统地、持续地培养人才，并且为人才搭建发挥能力的平台。只有这样，当领导者离开组织的时候，组织才会因为人才的支撑而屹立不倒。</p>',146)])])}const b=a(d,[["render",_]]);export{k as __pageData,b as default};
